package run.ikaros.planning; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Flux; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException;
@Service public class PersistentPlanningProjectSectionService implements PlanningProjectSectionService {private final PlanningProjectRepository projects;private final PlanningProjectSectionRepository sections;public PersistentPlanningProjectSectionService(PlanningProjectRepository p,PlanningProjectSectionRepository s){projects=p;sections=s;}public Mono<PlanningProjectSectionView> create(UUID owner,UUID project,CreatePlanningProjectSectionRequest r){return ownedProject(owner,project).then(Mono.defer(()->{Instant n=Instant.now();return sections.save(new PlanningProjectSectionEntity(null,project,r.name().trim(),r.position()==null?0:r.position(),n,n,null)).map(this::view);}));}public Flux<PlanningProjectSectionView> list(UUID owner,UUID project){return ownedProject(owner,project).thenMany(sections.findAllByProjectIdOrderByPositionAsc(project)).map(this::view);}public Mono<PlanningProjectSectionView> update(UUID owner,UUID id,UpdatePlanningProjectSectionRequest r){return owned(owner,id).flatMap(old->{if((old.version()==null?0:old.version())!=r.expectedVersion())return Mono.error(new ConflictException("Section 版本冲突"));return sections.save(new PlanningProjectSectionEntity(old.id(),old.projectId(),r.name().trim(),r.position()==null?old.position():r.position(),old.createdAt(),Instant.now(),old.version()));}).map(this::view);}public Mono<Void> delete(UUID owner,UUID id){return owned(owner,id).flatMap(sections::delete).then();}private Mono<PlanningProjectEntity> ownedProject(UUID owner,UUID id){return projects.findById(id).filter(p->p.ownerId().equals(owner)).switchIfEmpty(Mono.error(new NotFoundException("Project 不存在")));}private Mono<PlanningProjectSectionEntity> owned(UUID owner,UUID id){return sections.findById(id).flatMap(s->ownedProject(owner,s.projectId()).thenReturn(s)).switchIfEmpty(Mono.error(new NotFoundException("Section 不存在")));}private PlanningProjectSectionView view(PlanningProjectSectionEntity x){return new PlanningProjectSectionView(x.id(),x.projectId(),x.name(),x.position(),x.createdAt(),x.updatedAt(),x.version()==null?0:x.version());}}
